import { WeaviateClient } from "weaviate-client";
import { z } from "zod";
import {
  QueryAgentResponse,
  ProgressMessage,
  StreamedTokens,
  AskModeResponse,
  SuggestQueryResponse,
  OutputFormat,
  ParsedAskModeResponse,
} from "./response/response.js";
import {
  mapResponse,
  mapProgressMessageFromSSE,
  mapStreamedTokensFromSSE,
  mapAskModeResponse,
  mapSuggestQueryResponse,
  isZodSchema,
} from "./response/response-mapping.js";
import { mapApiResponse } from "./response/api-response-mapping.js";
import { fetchServerSentEvents } from "./response/server-sent-events.js";
import {
  mapCollections,
  QueryAgentCollection,
  QueryAgentCollectionConfig,
} from "./collection.js";
import { handleError } from "./response/error.js";
import { QueryAgentSearcher } from "./search.js";
import { SearchModeResponse } from "./response/response.js";
import { getHeaders } from "./connection.js";
import { hideImageBase64 } from "./media.js";

/**
 * An agent for executing agentic queries against Weaviate.
 *
 * For more information, see the [Weaviate Agents - Query Agent Docs](https://weaviate.io/developers/agents).
 */
export class QueryAgent {
  private collections?: (string | QueryAgentCollectionConfig)[];
  private systemPrompt?: string;
  private agentsHost: string;

  /**
   * Initialize the Query Agent.
   *
   * @param client - The Weaviate client connected to a Weaviate Cloud cluster.
   * @param options - Configuration for the agent.
   * @param options.collections - The collections to query. Either a list of strings, or a list of
   *   {@link QueryAgentCollectionConfig} objects. Will be overridden if passed in any of the agent's
   *   methods that support it.
   * @param options.systemPrompt - Optional prompt to control the tone, format, and style of the
   *   agent's final response. This prompt is both passed to the query writer agent, and applied
   *   when generating the answer after all research and data retrieval is complete.
   * @param options.agentsHost - Optional host of the agents service.
   */
  constructor(
    private client: WeaviateClient,
    {
      collections,
      systemPrompt,
      agentsHost = "https://api.agents.weaviate.io",
    }: QueryAgentOptions = {},
  ) {
    this.collections = collections;
    this.systemPrompt = systemPrompt;
    this.agentsHost = agentsHost;
  }

  /**
   * Run the query agent.
   *
   * @deprecated The `run` method is deprecated; use {@link ask} instead.
   * @param query - The natural language query string for the agent.
   * @param options - Options for this run.
   * @param options.collections - The collections to query. Will override any collections passed in the constructor.
   * @param options.context - Optional previous response from the agent.
   * @returns The response from the query agent.
   */
  async run(
    query: string,
    { collections, context }: QueryAgentRunOptions = {},
  ): Promise<QueryAgentResponse> {
    const targetCollections = collections ?? this.collections;
    if (!targetCollections) {
      throw Error("No collections provided to the query agent.");
    }

    const { host, bearerToken, headers } =
      await this.client.getConnectionDetails();

    const response = await fetch(`${this.agentsHost}/agent/query`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: [REDACTED],
        "X-Weaviate-Cluster-Url": host,
        "X-Agent-Request-Origin": "typescript-client",
      },
      body: JSON.stringify({
        headers,
        query,
        collections: mapCollections(targetCollections),
        system_prompt: this.systemPrompt,
        previous_response: context ? mapApiResponse(context) : undefined,
        result_evaluation: "none",
      }),
    });

    if (!response.ok) {
      await handleError(await response.text());
    }

    return mapResponse(await response.json());
  }

  /** @hidden */
  ask<S extends z.ZodType>(
    query: QueryAgentQuery,
    options: QueryAgentAskOptions & { outputFormat: S },
  ): Promise<ParsedAskModeResponse<z.infer<S>>>;
  /** @hidden */
  ask(
    query: QueryAgentQuery,
    options: QueryAgentAskOptions & { outputFormat: Record<string, unknown> },
  ): Promise<ParsedAskModeResponse<Record<string, unknown>>>;
  /**
   * Run the Query Agent ask mode.
   *
   * Performs an agentic search on the collections and returns a natural language answer to the query.
   *
   * @param query - The natural language query string, or a list of chat messages, for the agent.
   * @param options - Options for this ask invocation.
   * @param options.collections - The collections to query. Either a list of strings, or a list of
   *   {@link QueryAgentCollectionConfig} objects. Will override any collections passed in the constructor.
   * @param options.resultEvaluation - One of `"llm"` or `"none"`.
   *   If `"llm"`, the final answer will be cross-compared to the sources, and those sources will be
   *   filtered to only those in the answer. Also populates the `missingInformation` and
   *   `isPartialAnswer` fields of the response.
   *   If `"none"`, the result will not be evaluated, and the sources will not be filtered.
   *   Defaults to `"none"`.
   * @param options.outputFormat - The structured output format to return. Either a Zod schema, a JSON Schema object, or undefined.
   *   If a Zod schema is provided, the final answer will be parsed and validated into the schema, and the response will be returned as a {@link ParsedAskModeResponse} whose `finalAnswerParsed` is typed as `z.infer<typeof schema>`.
   *   If a JSON Schema object (Draft 2020-12) is provided, the final answer will be parsed as JSON, and the response will be returned as a {@link ParsedAskModeResponse} whose `finalAnswerParsed` is typed as `Record<string, unknown>`.
   *   If undefined (the default, no structured output), the answer is plain text on `finalAnswer` and an {@link AskModeResponse} is returned.
   *   To generate an image, include a {@link GeneratedImage} field in a Zod schema. The generated image is returned as a base64 PNG on that field's `base64` in `finalAnswerParsed`.
   * @returns An {@link AskModeResponse} (or {@link ParsedAskModeResponse} when `outputFormat` is set)
   *   which contains the final answer, sources, and other metadata such as the searches performed,
   *   usage and total time.
   *
   * @example
   * ```ts
   * const agent = new QueryAgent(client, { collections: ["FinancialContracts"] });
   * const response = await agent.ask(
   *   "What are the terms of the contract signed by John Smith in May 2025?",
   * );
   * ```
   *
   * @example Structured output with a Zod schema. The final answer is parsed and
   * validated into the schema, and exposed (typed) on `finalAnswerParsed`.
   * ```ts
   * import { z } from "zod";
   *
   * const CitedText = z.object({
   *   text: z.string(),
   *   sources: z
   *     .array(z.string())
   *     .describe("The sources that support this section of text. Can be empty."),
   * });
   * const AnswerWithSources = z.object({ texts: z.array(CitedText) });
   *
   * const agent = new QueryAgent(client, { collections: ["FinancialContracts"] });
   * const result = await agent.ask(
   *   "What contracts were signed by Jane Doe in 2024? What were they about?",
   *   { outputFormat: AnswerWithSources },
   * );
   * // result.finalAnswerParsed is typed as { texts: { text: string; sources: string[] }[] }
   * console.log(result.finalAnswerParsed.texts);
   * ```
   *
   * @example Image generation. Each image field is returned with the generated image
   * as base64. Use {@link generatedImageWithOptions} to set options such as the shape.
   * ```ts
   * import { z } from "zod";
   * import { GeneratedImage } from "weaviate-agents";
   *
   * const AnswerWithImage = z.object({
   *   answer: z.string(),
   *   image: GeneratedImage.describe("An advertisement for the product."),
   * });
   *
   * const agent = new QueryAgent(client, { collections: ["ECommerce"] });
   * const result = await agent.ask("What is the best selling product?", {
   *   outputFormat: AnswerWithImage,
   * });
   * const imageBytes = Buffer.from(result.finalAnswerParsed.image.base64, "base64");
   * ```
   */
  ask(
    query: QueryAgentQuery,
    options?: QueryAgentAskOptions,
  ): Promise<AskModeResponse>;
  async ask(
    query: QueryAgentQuery,
    {
      collections,
      resultEvaluation,
      outputFormat,
    }: QueryAgentAskOptions & { outputFormat?: OutputFormat } = {},
  ): Promise<AskModeResponse | ParsedAskModeResponse<unknown>> {
    const targetCollections = this.validateCollections(collections);
    const { requestHeaders, connectionHeaders } = await getHeaders(this.client);

    const response = await fetch(`${this.agentsHost}/query/ask`, {
      method: "POST",
      headers: requestHeaders,
      body: JSON.stringify({
        headers: connectionHeaders,
        query: typeof query === "string" ? query : { messages: query },
        collections: mapCollections(targetCollections),
        system_prompt: this.systemPrompt,
        result_evaluation: resultEvaluation ?? "none",
        output_format: mapOutputFormat(outputFormat),
      }),
    });

    if (!response.ok) {
      await handleError(await response.text());
    }

    const json = await response.json();
    return outputFormat === undefined
      ? mapAskModeResponse(json)
      : mapAskModeResponse(json, outputFormat);
  }

  /** @hidden */
  stream(
    query: string,
    options: QueryAgentStreamOptions & {
      includeProgress: false;
      includeFinalState: false;
    },
  ): AsyncGenerator<StreamedTokens>;
  /** @hidden */
  stream(
    query: string,
    options: QueryAgentStreamOptions & {
      includeProgress: false;
      includeFinalState?: true;
    },
  ): AsyncGenerator<StreamedTokens | QueryAgentResponse>;
  /** @hidden */
  stream(
    query: string,
    options: QueryAgentStreamOptions & {
      includeProgress?: true;
      includeFinalState: false;
    },
  ): AsyncGenerator<ProgressMessage | StreamedTokens>;
  /**
   * Stream responses from the query agent.
   *
   * @deprecated The `stream` method is deprecated; use {@link askStream} instead.
   * @param query - The natural language query string for the agent.
   * @param options - Options for the stream.
   * @param options.collections - The collections to query. Will override any collections passed in the constructor.
   * @param options.context - Optional previous response from the agent.
   * @param options.includeProgress - Whether to include progress messages in the stream. These are
   *   informational messages about the progress of the agent's search.
   * @param options.includeFinalState - Whether to include the final state in the stream. This is
   *   the final {@link QueryAgentResponse}, yielded as the last item in the stream.
   * @returns An async generator yielding {@link ProgressMessage}, {@link StreamedTokens}, and a
   *   final {@link QueryAgentResponse}, depending on the include flags.
   */
  stream(
    query: string,
    options?: QueryAgentStreamOptions & {
      includeProgress?: true;
      includeFinalState?: true;
    },
  ): AsyncGenerator<ProgressMessage | StreamedTokens | QueryAgentResponse>;
  async *stream(
    query: string,
    {
      collections,
      context,
      includeProgress,
      includeFinalState,
    }: QueryAgentStreamOptions = {},
  ): AsyncGenerator<ProgressMessage | StreamedTokens | QueryAgentResponse> {
    const targetCollections = collections ?? this.collections;

    if (!targetCollections) {
      throw Error("No collections provided to the query agent.");
    }

    const { host, bearerToken, headers } =
      await this.client.getConnectionDetails();

    const sseStream = fetchServerSentEvents(
      `${this.agentsHost}/agent/stream_query`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: [REDACTED],
          "X-Weaviate-Cluster-Url": host,
          "X-Agent-Request-Origin": "typescript-client",
        },
        body: JSON.stringify({
          headers,
          query,
          collections: mapCollections(targetCollections),
          system_prompt: this.systemPrompt,
          previous_response: context ? mapApiResponse(context) : undefined,
          include_progress: includeProgress ?? true,
          include_final_state: includeFinalState ?? true,
          result_evaluation: "none",
        }),
      },
    );

    for await (const event of sseStream) {
      if (event.event === "error") {
        await handleError(event.data);
      }

      let output: ProgressMessage | StreamedTokens | QueryAgentResponse;
      if (event.event === "progress_message") {
        output = mapProgressMessageFromSSE(event);
      } else if (event.event === "streamed_tokens") {
        output = mapStreamedTokensFromSSE(event);
      } else if (event.event === "final_state") {
        output = mapResponse(JSON.parse(event.data));
      } else {
        throw new Error(`Unexpected event type: ${event.event}: ${event.data}`);
      }

      yield output;
    }
  }

  /** @hidden */
  askStream<S extends z.ZodType>(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat: S;
      includeProgress: false;
      includeFinalState: false;
    },
  ): AsyncGenerator<StreamedTokens>;
  /** @hidden */
  askStream<S extends z.ZodType>(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat: S;
      includeProgress: false;
      includeFinalState?: true;
    },
  ): AsyncGenerator<StreamedTokens | ParsedAskModeResponse<z.infer<S>>>;
  /** @hidden */
  askStream<S extends z.ZodType>(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat: S;
      includeProgress?: true;
      includeFinalState: false;
    },
  ): AsyncGenerator<ProgressMessage | StreamedTokens>;
  /** @hidden */
  askStream<S extends z.ZodType>(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat: S;
      includeProgress?: true;
      includeFinalState?: true;
    },
  ): AsyncGenerator<
    ProgressMessage | StreamedTokens | ParsedAskModeResponse<z.infer<S>>
  >;
  /** @hidden */
  askStream(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat: Record<string, unknown>;
      includeProgress: false;
      includeFinalState: false;
    },
  ): AsyncGenerator<StreamedTokens>;
  /** @hidden */
  askStream(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat: Record<string, unknown>;
      includeProgress: false;
      includeFinalState?: true;
    },
  ): AsyncGenerator<
    StreamedTokens | ParsedAskModeResponse<Record<string, unknown>>
  >;
  /** @hidden */
  askStream(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat: Record<string, unknown>;
      includeProgress?: true;
      includeFinalState: false;
    },
  ): AsyncGenerator<ProgressMessage | StreamedTokens>;
  /** @hidden */
  askStream(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat: Record<string, unknown>;
      includeProgress?: true;
      includeFinalState?: true;
    },
  ): AsyncGenerator<
    | ProgressMessage
    | StreamedTokens
    | ParsedAskModeResponse<Record<string, unknown>>
  >;
  /** @hidden */
  askStream(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat?: undefined;
      includeProgress: false;
      includeFinalState: false;
    },
  ): AsyncGenerator<StreamedTokens>;
  /** @hidden */
  askStream(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat?: undefined;
      includeProgress: false;
      includeFinalState?: true;
    },
  ): AsyncGenerator<StreamedTokens | AskModeResponse>;
  /** @hidden */
  askStream(
    query: QueryAgentQuery,
    options: QueryAgentAskStreamOptions & {
      outputFormat?: undefined;
      includeProgress?: true;
      includeFinalState: false;
    },
  ): AsyncGenerator<ProgressMessage | StreamedTokens>;
  /**
   * Run the Query Agent ask mode and stream the response.
   *
   * @param query - The natural language query string, or a list of chat messages, for the agent.
   * @param options - Options for the ask stream.
   * @param options.collections - The collections to query. Either a list of strings, or a list of
   *   {@link QueryAgentCollectionConfig} objects. Will override any collections passed in the constructor.
   * @param options.includeProgress - Whether to include progress messages in the stream. These are
   *   informational messages about the progress of the agent's search.
   * @param options.includeFinalState - Whether to include the final state in the stream. This is
   *   the final {@link AskModeResponse}, yielded as the last item in the stream.
   * @param options.resultEvaluation - One of `"llm"` or `"none"`.
   *   If `"llm"`, the final answer will be cross-compared to the sources, and those sources will be
   *   filtered to only those in the answer. Also populates the `missingInformation` and
   *   `isPartialAnswer` fields of the response.
   *   If `"none"`, the result will not be evaluated, and the sources will not be filtered.
   *   Defaults to `"none"`.
   * @param options.outputFormat - The structured output format to return. Either a Zod schema, a JSON Schema object, or undefined.
   *   If a Zod schema is provided, the final answer will be parsed and validated into the schema, and the response will be returned as a `ParsedAskModeResponse` with the inferred type.
   *   If a JSON Schema object is provided, the final answer will be parsed as JSON, and the response will be returned as a `ParsedAskModeResponse` with the type `Record<string, unknown>`.
   *   If undefined, the final answer will be returned as a `AskModeResponse` with the type `string`.
   *   To generate an image, include a {@link GeneratedImage} field in a Zod schema. The generated image is returned as a base64 PNG on that field's `base64` in `finalAnswerParsed`.
   *   The streamed tokens of the final answer never include `base64`. It is added after generation, so it only appears in the final state.
   * @returns An async generator yielding any of the following:
   *
   * - {@link ProgressMessage}: informational messages about the progress of the agent's search
   *   (if `includeProgress` is `true`).
   * - {@link StreamedTokens}: token deltas from the agent's response.
   * - {@link AskModeResponse}: the final response, yielded as the last item in the stream
   *   (if `includeFinalState` is `true`).
   *
   * @example
   * ```ts
   * const agent = new QueryAgent(client, { collections: ["FinancialContracts"] });
   * for await (const event of agent.askStream(
   *   "What are the terms of the contract signed by John Smith in May 2025?",
   * )) {
   *   if ("finalAnswer" in event) {
   *     // AskModeResponse
   *     console.log(event.finalAnswer);
   *   } else if ("delta" in event) {
   *     // StreamedTokens
   *     process.stdout.write(event.delta);
   *   } else {
   *     // ProgressMessage
   *     console.log(event.message);
   *   }
   * }
   * ```
   *
   * @example Structured output with a Zod schema. When `includeFinalState` is on
   * (the default), the final-state event is a {@link ParsedAskModeResponse} whose
   * `finalAnswerParsed` is typed from the schema.
   * ```ts
   * import { z } from "zod";
   *
   * const CitedText = z.object({
   *   text: z.string(),
   *   sources: z
   *     .array(z.string())
   *     .describe("The sources that support this section of text. Can be empty."),
   * });
   * const AnswerWithSources = z.object({ texts: z.array(CitedText) });
   *
   * const agent = new QueryAgent(client, { collections: ["FinancialContracts"] });
   * for await (const event of agent.askStream(
   *   "What contracts were signed by Jane Doe in 2024? What were they about?",
   *   { outputFormat: AnswerWithSources },
   * )) {
   *   if ("finalAnswerParsed" in event) {
   *     // ParsedAskModeResponse — finalAnswerParsed is typed from the schema
   *     console.log(event.finalAnswerParsed.texts);
   *   } else if ("delta" in event) {
   *     process.stdout.write(event.delta);
   *   } else {
   *     console.log(event.message);
   *   }
   * }
   * ```
   *
   * @example Image generation. The image's base64 is only populated on the final state.
   * ```ts
   * import { z } from "zod";
   * import { GeneratedImage } from "weaviate-agents";
   *
   * const AnswerWithImage = z.object({
   *   answer: z.string(),
   *   image: GeneratedImage.describe("An advertisement for the product."),
   * });
   *
   * const agent = new QueryAgent(client, { collections: ["ECommerce"] });
   * for await (const event of agent.askStream("What is the best selling product?", {
   *   outputFormat: AnswerWithImage,
   * })) {
   *   if ("finalAnswerParsed" in event) {
   *     const imageBytes = Buffer.from(event.finalAnswerParsed.image.base64, "base64");
   *   } else if ("delta" in event) {
   *     process.stdout.write(event.delta);
   *   } else {
   *     console.log(event.message);
   *   }
   * }
   * ```
   */
  askStream(
    query: QueryAgentQuery,
    options?: QueryAgentAskStreamOptions & {
      outputFormat?: undefined;
      includeProgress?: true;
      includeFinalState?: true;
    },
  ): AsyncGenerator<ProgressMessage | StreamedTokens | AskModeResponse>;
  async *askStream(
    query: QueryAgentQuery,
    {
      collections,
      includeProgress,
      includeFinalState,
      resultEvaluation,
      outputFormat,
    }: QueryAgentAskStreamOptions & { outputFormat?: OutputFormat } = {},
  ): AsyncGenerator<
    | ProgressMessage
    | StreamedTokens
    | AskModeResponse
    | ParsedAskModeResponse<unknown>
  > {
    const targetCollections = collections ?? this.collections;

    if (!targetCollections) {
      throw Error("No collections provided to the query agent.");
    }

    const { host, bearerToken, headers } =
      await this.client.getConnectionDetails();

    const sseStream = fetchServerSentEvents(
      `${this.agentsHost}/query/stream_ask`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: [REDACTED],
          "X-Weaviate-Cluster-Url": host,
          "X-Agent-Request-Origin": "typescript-client",
        },
        body: JSON.stringify({
          headers,
          query: typeof query === "string" ? query : { messages: query },
          collections: mapCollections(targetCollections),
          system_prompt: this.systemPrompt,
          include_progress: includeProgress ?? true,
          include_final_state: includeFinalState ?? true,
          result_evaluation: resultEvaluation ?? "none",
          output_format: mapOutputFormat(outputFormat),
        }),
      },
    );

    for await (const event of sseStream) {
      if (event.event === "error") {
        await handleError(event.data);
      }

      let output:
        | ProgressMessage
        | StreamedTokens
        | AskModeResponse
        | ParsedAskModeResponse<unknown>;
      if (event.event === "progress_message") {
        output = mapProgressMessageFromSSE(event);
      } else if (event.event === "streamed_tokens") {
        output = mapStreamedTokensFromSSE(event);
      } else if (event.event === "final_state") {
        const finalState = JSON.parse(event.data);
        output =
          outputFormat === undefined
            ? mapAskModeResponse(finalState)
            : mapAskModeResponse(finalState, outputFormat);
      } else {
        throw new Error(`Unexpected event type: ${event.event}: ${event.data}`);
      }

      yield output;
    }
  }

  /**
   * Run the Query Agent search-only mode.
   *
   * Sends the initial search request and returns a {@link SearchModeResponse} containing the
   * first page of results. To paginate, call `response.next({ limit, offset })` on the returned
   * response. This reuses the same underlying searches to ensure a consistent result set across
   * pages.
   *
   * @param query - The natural language query string, or a list of chat messages, for the agent.
   * @param options - Options for this search invocation.
   * @param options.limit - The maximum number of results to return for the first page. Defaults to 20.
   * @param options.collections - The collections to query. Either a list of strings, or a list of
   *   {@link QueryAgentCollectionConfig} objects. Will override any collections passed in the constructor.
   * @param options.diversityWeight - Optional number between `0.0` and `1.0` to diversify results
   *   with MMR reranking. Higher values push for more topical variety at the cost of relevance.
   *   Defaults to no diversity.
   * @param options.filtering - The filtering strategy: `"recall"` for broader retrieval or
   *   `"precision"` for more targeted results. Defaults to `"recall"`.
   * @param options.effort - The amount of effort the agent should put into the search. One of
   *   `"medium"`, `"high"`, or `"ultrahigh"`. Higher effort may improve result quality at the
   *   expense of increased latency and cost.
   * @returns A {@link SearchModeResponse} for the first page of results. Use
   *   `response.next({ limit, offset })` to paginate.
   *
   * @example
   * ```ts
   * const agent = new QueryAgent(client, { collections: ["FinancialContracts"] });
   * const page1 = await agent.search("Find all NDAs signed by Jane Doe in 2024.", { limit: 5 });
   * const page2 = await page1.next({ limit: 5, offset: 5 });
   * const page3 = await page2.next({ limit: 5, offset: 10 });
   * ```
   */
  async search(
    query: QueryAgentQuery,
    {
      limit = 20,
      collections,
      diversityWeight,
      filtering,
      effort,
    }: QueryAgentSearchOnlyOptions = {},
  ): Promise<SearchModeResponse> {
    const searcher = new QueryAgentSearcher(
      this.client,
      query,
      this.validateCollections(collections),
      this.systemPrompt,
      this.agentsHost,
      diversityWeight,
      filtering,
      effort,
    );

    return searcher.run({ limit, offset: 0 });
  }

  /**
   * Suggest queries for the data in your collections.
   *
   * Uses the agent to generate example queries that can be run against the given collections.
   * This can help users discover what kinds of questions they can ask, or generate example prompts
   * for a dataset.
   *
   * @param options - Options for the suggest-queries request.
   * @param options.collections - Optional override for the collections configured at instantiation.
   *   Either a list of strings, or a list of {@link QueryAgentCollectionConfig} objects.
   * @param options.numQueries - The number of queries to suggest. Defaults to 3.
   * @param options.instructions - Optional natural language guidance for the style, topic, or
   *   language of the suggested queries. Supplied in addition to the agent's system instructions.
   * @param options.conversation - Optional conversation history to contextualise suggested queries
   *   as follow-up questions. Each element is a {@link ChatMessage} with `role` and `content`.
   * @returns A {@link SuggestQueryResponse} containing the list of suggested queries, along with
   *   additional metadata if present.
   *
   * @example
   * ```ts
   * const agent = new QueryAgent(client, { collections: ["FinancialContracts"] });
   * const suggestions = await agent.suggestQueries({
   *   collections: ["Products"],
   *   numQueries: 5,
   *   instructions: "Focus on questions about eco-friendly features.",
   *   conversation: [
   *     { role: "user", content: "What topics are covered?" },
   *     { role: "assistant", content: "The collection covers ML and economics." },
   *   ],
   * });
   * ```
   */
  async suggestQueries({
    collections,
    numQueries,
    instructions,
    conversation,
  }: QueryAgentSuggestQueriesOptions = {}): Promise<SuggestQueryResponse> {
    const targetCollections = this.validateCollections(collections);
    const { requestHeaders, connectionHeaders } = await getHeaders(this.client);

    const body: Record<string, unknown> = {
      headers: connectionHeaders,
      collections: mapCollections(targetCollections),
      num_queries: numQueries ?? 3,
    };
    if (instructions !== undefined) {
      body.instructions = instructions;
    }
    if (conversation !== undefined) {
      body.conversation_context = { messages: conversation };
    }

    const response = await fetch(`${this.agentsHost}/query/suggest_queries`, {
      method: "POST",
      headers: requestHeaders,
      body: JSON.stringify(body),
    });

    if (!response.ok) {
      await handleError(await response.text());
    }

    return mapSuggestQueryResponse(await response.json());
  }

  private validateCollections = (
    collections?: QueryAgentCollection[],
  ): QueryAgentCollection[] => {
    const targetCollections = collections ?? this.collections;

    if (!targetCollections) {
      throw Error("No collections provided to the query agent.");
    }

    return targetCollections;
  };
}

/**
 * Convert a user-supplied {@link OutputFormat} into the JSON Schema the agents
 * API expects on the request body: a Zod schema is serialised to a Draft
 * 2020-12 JSON Schema, a raw JSON Schema object is sent through unchanged, and
 * `undefined` (no structured output) stays `undefined`.
 */
const mapOutputFormat = (
  outputFormat: OutputFormat | undefined,
): Record<string, unknown> | undefined => {
  if (outputFormat === undefined) {
    return undefined;
  }
  return isZodSchema(outputFormat)
    ? z.toJSONSchema(outputFormat, {
        target: "draft-2020-12",
        override: hideImageBase64,
      })
    : outputFormat;
};

/** Options for constructing a {@link QueryAgent}. */
export type QueryAgentOptions = {
  /**
   * The collections to query. Either a list of strings, or a list of
   * {@link QueryAgentCollectionConfig} objects. Will be overridden if passed in any of the
   * agent's methods that support it.
   */
  collections?: QueryAgentCollection[];
  /**
   * Optional prompt to control the tone, format, and style of the agent's final response. This
   * prompt is both passed to the query writer agent, and applied when generating the answer
   * after all research and data retrieval is complete.
   */
  systemPrompt?: string;
  /** Optional host of the agents service. */
  agentsHost?: string;
};

/** The query for a Query Agent invocation. Either a natural language string or a list of chat messages. */
export type QueryAgentQuery = string | ChatMessage[];

/** A single chat message in a conversation context passed to the Query Agent. */
export type ChatMessage = {
  role: "user" | "assistant";
  content: string;
};

/**
 * Options for {@link QueryAgent.run}.
 *
 * @deprecated `run` is deprecated; use {@link QueryAgent.ask} with {@link QueryAgentAskOptions} instead.
 */
export type QueryAgentRunOptions = {
  /** The collections to query. Will override any collections passed in the constructor. */
  collections?: (string | QueryAgentCollectionConfig)[];
  /** Optional previous response from the agent. */
  context?: QueryAgentResponse;
};

/**
 * Controls how the agent evaluates the final result.
 *
 * - `"llm"`: cross-compares the final answer to the sources, filters those sources to only the
 *   ones used in the answer, and populates `missingInformation` and `isPartialAnswer`.
 * - `"none"`: the result is not evaluated and sources are not filtered.
 */
export type ResultEvaluation = "llm" | "none";

/** Options for {@link QueryAgent.ask}. */
export type QueryAgentAskOptions = {
  /**
   * The collections to query. Either a list of strings, or a list of
   * {@link QueryAgentCollectionConfig} objects. Will override any collections passed in the constructor.
   */
  collections?: (string | QueryAgentCollectionConfig)[];
  /** How the agent should evaluate the final result. See {@link ResultEvaluation}. Defaults to `"none"`. */
  resultEvaluation?: ResultEvaluation;
};

/**
 * Options for {@link QueryAgent.stream}.
 *
 * @deprecated `stream` is deprecated; use {@link QueryAgent.askStream} with {@link QueryAgentAskStreamOptions} instead.
 */
export type QueryAgentStreamOptions = {
  /** The collections to query. Will override any collections passed in the constructor. */
  collections?: (string | QueryAgentCollectionConfig)[];
  /** Optional previous response from the agent. */
  context?: QueryAgentResponse;
  /**
   * Whether to include progress messages in the stream. These are informational messages about the
   * progress of the agent's search.
   */
  includeProgress?: boolean;
  /**
   * Whether to include the final state in the stream. This is the final {@link QueryAgentResponse},
   * yielded as the last item in the stream.
   */
  includeFinalState?: boolean;
};

/** Options for {@link QueryAgent.askStream}. */
export type QueryAgentAskStreamOptions = {
  /**
   * The collections to query. Either a list of strings, or a list of
   * {@link QueryAgentCollectionConfig} objects. Will override any collections passed in the constructor.
   */
  collections?: (string | QueryAgentCollectionConfig)[];
  /**
   * Whether to include progress messages in the stream. These are informational messages about the
   * progress of the agent's search.
   */
  includeProgress?: boolean;
  /**
   * Whether to include the final state in the stream. This is the final {@link AskModeResponse},
   * yielded as the last item in the stream.
   */
  includeFinalState?: boolean;
  /** How the agent should evaluate the final result. See {@link ResultEvaluation}. Defaults to `"none"`. */
  resultEvaluation?: ResultEvaluation;
};

/** Options for {@link QueryAgent.search}. */
export type QueryAgentSearchOnlyOptions = {
  /** The maximum number of results to return for the first page. Defaults to 20. */
  limit?: number;
  /**
   * The collections to query. Either a list of strings, or a list of
   * {@link QueryAgentCollectionConfig} objects. Will override any collections passed in the constructor.
   */
  collections?: (string | QueryAgentCollectionConfig)[];
  /**
   * Optional number between `0.0` and `1.0` to diversify results with MMR reranking. Higher values
   * push for more topical variety at the cost of relevance. Defaults to no diversity.
   */
  diversityWeight?: number;
  /**
   * The filtering strategy to use for the search. `"recall"` optimizes for finding all relevant
   * results (broader retrieval), while `"precision"` optimizes for accuracy of returned results
   * (narrower, more targeted retrieval).
   */
  filtering?: "recall" | "precision";
  /**
   * The amount of effort the agent should put into the search. One of `"medium"`, `"high"`, or
   * `"ultrahigh"`. Higher effort may improve result quality at the expense of increased latency
   * and cost.
   */
  effort?: "medium" | "high" | "ultrahigh";
};

/** Options for {@link QueryAgent.suggestQueries}. */
export type QueryAgentSuggestQueriesOptions = {
  /**
   * Optional override for the collections configured at instantiation. Either a list of strings,
   * or a list of {@link QueryAgentCollectionConfig} objects.
   */
  collections?: (string | QueryAgentCollectionConfig)[];
  /** The number of queries to suggest. Defaults to 3. */
  numQueries?: number;
  /**
   * Optional natural language guidance for the style, topic, or language of the suggested queries.
   * Supplied in addition to the agent's system instructions.
   */
  instructions?: string;
  /**
   * Optional conversation history to contextualise suggested queries as follow-up questions.
   * Each element is a {@link ChatMessage} with `role` and `content`.
   */
  conversation?: ChatMessage[];
};

import { WeaviateClient } from "weaviate-client";
import {
  SearchExecutionOptions,
  SearchModeResponse,
} from "./response/response.js";
import { mapSearchOnlyResponse } from "./response/response-mapping.js";
import { mapCollections } from "./collection.js";
import { handleError } from "./response/error.js";
import { ApiSearch, ApiSearchModeResponse } from "./response/api-response.js";
import { QueryAgentQuery } from "./agent.js";
import { QueryAgentCollection } from "./collection.js";
import { getHeaders } from "./connection.js";

/**
 * A configured searcher for the QueryAgent.
 *
 * This is used internally by the QueryAgent class to run search-mode queries.
 * After the first request is made, the underlying searches are cached and can
 * be reused for paginating through the a consistent set of results.
 */
export class QueryAgentSearcher {
  private cachedSearches?: ApiSearch[];

  constructor(
    private client: WeaviateClient,
    private query: QueryAgentQuery,
    private collections: QueryAgentCollection[],
    private systemPrompt: string | undefined,
    private agentsHost: string,
    private diversityWeight: number | undefined,
    private filtering: "recall" | "precision" | undefined,
    private effort: "medium" | "high" | "ultrahigh" | undefined,
  ) {}

  private buildRequestBody(
    limit: number,
    offset: number,
    connectionHeaders: HeadersInit | undefined,
  ) {
    // Fields that apply to every request (both the initial search generation
    // and subsequent pagination requests) belong on `base`.
    const base = {
      headers: connectionHeaders,
      original_query:
        typeof this.query === "string" ? this.query : { messages: this.query },
      collections: mapCollections(this.collections),
      limit,
      offset,
      diversity_weight: this.diversityWeight,
      filtering: this.filtering,
      effort: this.effort,
    } as const;
    if (this.cachedSearches === undefined) {
      return {
        ...base,
        searches: null,
        system_prompt: this.systemPrompt || null,
      };
    }
    return {
      ...base,
      searches: this.cachedSearches,
    };
  }

  /**
   * Run the search-only agent with the given limit and offset values.
   *
   * Calling this method multiple times on the same QueryAgentSearcher instance will result
   * in the same underlying searches being performed each time, allowing you to paginate
   * over a consistent results set.
   *
   * @param [options] - Options for executing the search
   * @param [options.limit] - The maximum number of results to return. Defaults to 20 if not specified.
   * @param [options.offset] - The offset to start from.
   * @returns A SearchModeResponse object containing the results, usage, and underlying searches performed.
   */
  async run({
    limit = 20,
    offset,
  }: SearchExecutionOptions): Promise<SearchModeResponse> {
    if (!this.collections || this.collections.length === 0) {
      throw Error("No collections provided to the query agent.");
    }
    const { requestHeaders, connectionHeaders } = await getHeaders(this.client);

    const response = await fetch(`${this.agentsHost}/query/search_only`, {
      method: "POST",
      headers: requestHeaders,
      body: JSON.stringify(
        this.buildRequestBody(limit, offset, connectionHeaders),
      ),
    });
    if (!response.ok) {
      await handleError(await response.text());
    }
    const parsedResponse = (await response.json()) as ApiSearchModeResponse;
    const { mappedResponse, apiSearches } =
      mapSearchOnlyResponse(parsedResponse);
    // If we successfully mapped the searches, cache them for the next request.
    // Since this cache is a private internal value, there's not point in mapping
    // back and forth between the exported and API types, so we cache apiSearches
    if (mappedResponse.searches !== undefined) {
      this.cachedSearches = apiSearches;
    }
    return {
      ...mappedResponse,
      next: async (options: SearchExecutionOptions) => this.run(options),
    };
  }
}

import {
  AggregationResult,
  PropertyAggregation,
  PropertyFilter,
  QueryAgentResponse,
  SearchResult,
  Source,
  Usage,
  DateFilterValue,
} from "./response.js";

import {
  ApiAggregationResult,
  ApiPropertyAggregation,
  ApiPropertyFilter,
  ApiQueryAgentResponse,
  ApiSearchResult,
  ApiSource,
  ApiUsage,
  ApiDateFilterValue,
} from "./api-response.js";

export const mapApiResponse = (
  response: QueryAgentResponse,
): ApiQueryAgentResponse => ({
  original_query: response.originalQuery,
  collection_names: response.collectionNames,
  searches: mapApiSearches(response.searches),
  aggregations: mapApiAggregations(response.aggregations),
  usage: mapApiUsage(response.usage),
  total_time: response.totalTime,
  is_partial_answer: response.isPartialAnswer,
  missing_information: response.missingInformation,
  final_answer: response.finalAnswer,
  sources: mapApiSources(response.sources),
});

const mapApiSearches = (searches: SearchResult[][]): ApiSearchResult[][] =>
  searches.map((searchGroup) =>
    searchGroup.map((result) => ({
      collection: result.collection,
      queries: result.queries,
      filters: result.filters.map(mapApiPropertyFilters),
      filter_operators: result.filterOperators,
    })),
  );

const mapDateFilterValue = (
  value: DateFilterValue,
): ApiDateFilterValue | undefined => {
  if ("exactTimestamp" in value) {
    return {
      exact_timestamp: value.exactTimestamp,
      operator: value.operator,
    };
  } else if (
    "dateFrom" in value &&
    "dateTo" in value &&
    value.dateFrom != null &&
    value.dateTo != null
  ) {
    return {
      date_from: value.dateFrom,
      date_to: value.dateTo,
      inclusive_from: value.inclusiveFrom,
      inclusive_to: value.inclusiveTo,
    };
  } else if ("dateFrom" in value && value.dateFrom != null) {
    return {
      date_from: value.dateFrom,
      inclusive_from: value.inclusiveFrom,
    };
  } else if ("dateTo" in value && value.dateTo != null) {
    return {
      date_to: value.dateTo,
      inclusive_to: value.inclusiveTo,
    };
  } else {
    return undefined;
  }
};

const mapApiPropertyFilters = (
  filters: PropertyFilter[],
): ApiPropertyFilter[] =>
  filters
    .map((filter) => {
      switch (filter.filterType) {
        case "integer":
          return {
            filter_type: "integer",
            property_name: filter.propertyName,
            operator: filter.operator,
            value: filter.value,
          };
        case "integerArray":
          return {
            filter_type: "integer_array",
            property_name: filter.propertyName,
            operator: filter.operator,
            value: filter.value,
          };
        case "text":
          return {
            filter_type: "text",
            property_name: filter.propertyName,
            operator: filter.operator,
            value: filter.value,
          };
        case "textArray":
          return {
            filter_type: "text_array",
            property_name: filter.propertyName,
            operator: filter.operator,
            value: filter.value,
          };
        case "boolean":
          return {
            filter_type: "boolean",
            property_name: filter.propertyName,
            operator: filter.operator,
            value: filter.value,
          };
        case "booleanArray":
          return {
            filter_type: "boolean_array",
            property_name: filter.propertyName,
            operator: filter.operator,
            value: filter.value,
          };
        case "dateRange":
          const value = mapDateFilterValue(filter.value);
          if (!value) {
            return undefined;
          }
          return {
            filter_type: "date_range",
            property_name: filter.propertyName,
            value,
          };
        case "dateArray":
          return {
            filter_type: "date_array",
            property_name: filter.propertyName,
            operator: filter.operator,
            value: filter.value,
          };
        case "geo":
          return {
            filter_type: "geo",
            property_name: filter.propertyName,
            latitude: filter.latitude,
            longitude: filter.longitude,
            max_distance_meters: filter.maxDistanceMeters,
          };
        case "isNull":
          return {
            filter_type: "is_null",
            property_name: filter.propertyName,
            is_null: filter.isNull,
          };
        case "uuid":
          return {
            filter_type: "uuid",
            property_name: filter.propertyName,
            operator: filter.operator,
            value: filter.value,
          };
        case "uuidArray":
          return {
            filter_type: "uuid_array",
            property_name: filter.propertyName,
            operator: filter.operator,
            value: filter.value,
          };
        default:
          return undefined;
      }
    })
    .filter((filter): filter is ApiPropertyFilter => filter !== undefined);

const mapApiAggregations = (
  aggregations: AggregationResult[][],
): ApiAggregationResult[][] =>
  aggregations.map((aggregationGroup) =>
    aggregationGroup.map((result) => ({
      collection: result.collection,
      search_query: result.searchQuery,
      groupby_property: result.groupbyProperty,
      aggregations: result.aggregations.map(mapApiPropertyAggregation),
      filters: mapApiPropertyFilters(result.filters),
    })),
  );

const mapApiPropertyAggregation = (
  aggregation: PropertyAggregation,
): ApiPropertyAggregation => ({
  property_name: aggregation.propertyName,
  metrics: aggregation.metrics,
  top_occurrences_limit:
    "topOccurrencesLimit" in aggregation
      ? aggregation.topOccurrencesLimit
      : undefined,
});

const mapApiUsage = (usage: Usage): ApiUsage => ({
  requests: usage.requests,
  request_tokens: usage.requestTokens,
  response_tokens: usage.responseTokens,
  total_tokens: usage.totalTokens,
  details: usage.details,
});

const mapApiSources = (sources: Source[]): ApiSource[] =>
  sources.map((source) => ({
    object_id: source.objectId,
    collection: source.collection,
  }));

